import CoreGraphics
import Foundation

enum ChartGrain {
    /// One seamless tile of two plate inks. The deterministic texture is used
    /// only when baking a terrain image, never regenerated by animation.
    static let image: CGImage? = {
        let w=160, h=160
        var random=SurveySeed(139623)
        var pixels=[UInt8](repeating:0,count:w*h*4)
        for y in 0..<h {
            for x in 0..<w {
                let k=(y*w+x)*4, speck=random.next()
                let alpha: CGFloat = speck > 0.87 ? 0.14 : (speck < 0.16 ? 0.095 : 0.026)
                let tint: [CGFloat] = speck > 0.52 ? [0.99,0.96,0.82] : [0.045,0.102,0.111]
                for channel in 0..<3 { pixels[k+channel]=UInt8(255*alpha*tint[channel]) }
                pixels[k+3]=UInt8(255*alpha)
            }
        }
        guard let provider=CGDataProvider(data:Data(pixels) as CFData) else { return nil }
        return CGImage(width:w,height:h,bitsPerComponent:8,bitsPerPixel:32,bytesPerRow:w*4,
                       space:CGColorSpace(name:CGColorSpace.sRGB)!,
                       bitmapInfo:CGBitmapInfo(rawValue:CGImageAlphaInfo.premultipliedLast.rawValue),
                       provider:provider,decode:nil,shouldInterpolate:false,intent:.defaultIntent)
    }()

    static func apply(to ctx: CGContext) {
        guard let image else { return }
        ctx.saveGState()
        ctx.setAlpha(0.36)
        ctx.interpolationQuality = .none
        ctx.draw(image,in:CGRect(x:0,y:0,width:120,height:120),byTiling:true)
        ctx.restoreGState()
    }
}
